const body = $json.body ?? $json;
const operation = body.operation;
if (!['chat', 'chat_guard', 'evaluation'].includes(operation)) throw new Error('Unsupported operation');
if (typeof body.message !== 'string' || !body.message.trim()) throw new Error('message is required');
const history = Array.isArray(body.history) ? body.history.slice(-10).flatMap(item => {
  if (!item || !['user', 'assistant'].includes(item.role) || typeof item.content !== 'string') return [];
  return [{ role: item.role, content: item.content.slice(0, 4000) }];
}) : [];
const system = typeof body.system === 'string' ? body.system.slice(0, 8000) : 'You are TalentBridge AI support.';
const maxTokens = Math.min(Math.max(Number(body.maxTokens) || 512, 1), 2048);
return [{ json: { model: typeof body.model === 'string' ? body.model : 'gpt-4o-mini', maxTokens, messages: [{ role: 'system', content: system }, ...history, { role: 'user', content: body.message.trim().slice(0, 12000) }] } }];

const message = $json.choices?.[0]?.message?.content ?? $json.message?.content ?? $json.message;
if (typeof message !== 'string' || !message.trim()) throw new Error('OpenAI returned no message');
return [{ json: { message: message.trim() } }];
